#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXN 100000
#define MAXNODE (4 * MAXN + 5)
#define POOL_SIZE (10 * MAXN + 5)

typedef struct {
    int val;
    int cnt;
    unsigned short mask;
} Entry;

typedef struct {
    long long cnt;
    int pref_len;
    Entry* pref;
    int suff_len;
    Entry* suff;
    int left_primes[10];
    int left_p_len;
    int right_primes[10];
    int right_p_len;
} NodeView;

int S[MAXN + 1];
Entry pref_pool[POOL_SIZE];
Entry suff_pool[POOL_SIZE];
int pref_top = 0, suff_top = 0;

int pref_off[MAXNODE], pref_len[MAXNODE];
int suff_off[MAXNODE], suff_len[MAXNODE];
long long cnt[MAXNODE];
int left_primes[MAXNODE][10], left_p_len[MAXNODE];
int right_primes[MAXNODE][10], right_p_len[MAXNODE];

int primes[4000], pc = 0;

void sieve(void) {
    bool comp[31624] = {0};
    for (int i = 2; i <= 31623; i++) {
        if (!comp[i]) {
            primes[pc++] = i;
            if ((long long)i * i <= 31623) {
                for (int j = i * i; j <= 31623; j += i)
                    comp[j] = 1;
            }
        }
    }
}

long long modpow(long long a, long long e, int mod) {
    long long res = 1;
    while (e) {
        if (e & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        e >>= 1;
    }
    return res;
}

bool isPrime(int n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    if (n % 3 == 0) return n == 3;
    if (n % 5 == 0) return n == 5;
    if (n % 7 == 0) return n == 7;

    int d = n - 1, s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        s++;
    }

    int bases[] = {2, 3, 5, 7, 11};
    for (int i = 0; i < 5; i++) {
        int a = bases[i];
        if (a >= n) continue;
        long long x = modpow(a, d, n);
        if (x == 1 || x == n - 1) continue;

        bool comp = true;
        for (int r = 1; r < s; r++) {
            x = (x * x) % n;
            if (x == n - 1) {
                comp = false;
                break;
            }
        }
        if (comp) return false;
    }
    return true;
}

int factorize(int x, int* out) {
    if (x == 1) return 0;
    if (isPrime(x)) {
        out[0] = x;
        return 1;
    }

    int n = x, cnt = 0;
    for (int i = 0; i < pc && (long long)primes[i] * primes[i] <= n; i++) {
        if (n % primes[i] == 0) {
            out[cnt++] = primes[i];
            while (n % primes[i] == 0) n /= primes[i];
        }
    }
    if (n > 1) out[cnt++] = n;
    return cnt;
}

static inline int gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static inline void append_entry(Entry* list, int* len, int val, int cnt, unsigned short mask) {
    if (*len > 0 && list[*len - 1].val == val) {
        list[*len - 1].cnt += cnt;
    } else {
        list[*len].val = val;
        list[*len].cnt = cnt;
        list[*len].mask = mask;
        (*len)++;
    }
}

static inline unsigned short map_mask(unsigned short m, int len, int* map) {
    unsigned short res = 0;
    for (int j = 0; j < len; j++) {
        if ((m >> j) & 1) {
            int i = map[j];
            if (i >= 0) res |= (1 << i);
        }
    }
    return res;
}

long long compute_cross(Entry* Lsuff, int llen, int* P_A, int lenA,
                        Entry* Rpref, int rlen, int* P_B, int lenB) {
    int common_count = 0;
    int a_bit[10], b_bit[10];

    for (int a = 0; a < lenA; a++) {
        for (int b = 0; b < lenB; b++) {
            if (P_A[a] == P_B[b]) {
                a_bit[common_count] = a;
                b_bit[common_count] = b;
                common_count++;
                break;
            }
        }
    }

    if (common_count == 0) return 0;

    int Lval[10] = {0};
    for (int j = 0; j < rlen; j++) {
        unsigned short m = Rpref[j].mask;
        for (int c = 0; c < common_count; c++) {
            if ((m >> b_bit[c]) & 1)
                Lval[c] = j + 1;
        }
    }

    long long pref_sum[33];
    pref_sum[0] = 0;
    for (int j = 0; j < rlen; j++) {
        pref_sum[j + 1] = pref_sum[j] + Rpref[j].cnt;
    }

    long long cross = 0;
    for (int i = 0; i < llen; i++) {
        unsigned short m = Lsuff[i].mask;
        int maxL = 0;
        for (int c = 0; c < common_count; c++) {
            if ((m >> a_bit[c]) & 1) {
                if (Lval[c] > maxL) maxL = Lval[c];
            }
        }
        cross += (long long)Lsuff[i].cnt * pref_sum[maxL];
    }
    return cross;
}

void copy_view(NodeView* dst, NodeView* src) {
    dst->cnt = src->cnt;
    dst->pref_len = src->pref_len;
    dst->suff_len = src->suff_len;
    dst->left_p_len = src->left_p_len;
    memcpy(dst->left_primes, src->left_primes, sizeof(int) * src->left_p_len);
    dst->right_p_len = src->right_p_len;
    memcpy(dst->right_primes, src->right_primes, sizeof(int) * src->right_p_len);

    for (int i = 0; i < src->pref_len; i++) dst->pref[i] = src->pref[i];
    for (int i = 0; i < src->suff_len; i++) dst->suff[i] = src->suff[i];
}

void merge_views(NodeView* res, NodeView* L, NodeView* R) {
    if (L->pref_len == 0) {
        copy_view(res, R);
        return;
    }
    if (R->pref_len == 0) {
        copy_view(res, L);
        return;
    }

    res->left_p_len = L->left_p_len;
    memcpy(res->left_primes, L->left_primes, sizeof(int) * L->left_p_len);
    res->right_p_len = R->right_p_len;
    memcpy(res->right_primes, R->right_primes, sizeof(int) * R->right_p_len);

    int L_total_gcd = L->pref[L->pref_len - 1].val;
    unsigned short L_total_mask = L->pref[L->pref_len - 1].mask;
    int R_total_gcd = R->suff[R->suff_len - 1].val;
    unsigned short R_total_mask = R->suff[R->suff_len - 1].mask;

    long long cross = compute_cross(
        L->suff, L->suff_len, L->right_primes, L->right_p_len,
        R->pref, R->pref_len, R->left_primes, R->left_p_len
    );

    res->cnt = L->cnt + R->cnt + cross;

    // Prefixos
    int len = 0;
    Entry* out = res->pref;
    for (int i = 0; i < L->pref_len; i++) out[len++] = L->pref[i];

    int mapRtoL[10];
    for (int j = 0; j < R->left_p_len; j++) {
        mapRtoL[j] = -1;
        for (int i = 0; i < L->left_p_len; i++) {
            if (R->left_primes[j] == L->left_primes[i]) {
                mapRtoL[j] = i;
                break;
            }
        }
    }

    for (int i = 0; i < R->pref_len; i++) {
        Entry e = R->pref[i];
        int val = gcd(L_total_gcd, e.val);
        unsigned short mapped = map_mask(e.mask, R->left_p_len, mapRtoL);
        unsigned short mask = L_total_mask & mapped;
        append_entry(out, &len, val, e.cnt, mask);
    }
    res->pref_len = len;

    // Sufixos
    len = 0;
    out = res->suff;
    for (int i = 0; i < R->suff_len; i++) out[len++] = R->suff[i];

    int mapLtoR[10];
    for (int j = 0; j < L->right_p_len; j++) {
        mapLtoR[j] = -1;
        for (int i = 0; i < R->right_p_len; i++) {
            if (L->right_primes[j] == R->right_primes[i]) {
                mapLtoR[j] = i;
                break;
            }
        }
    }

    for (int i = 0; i < L->suff_len; i++) {
        Entry e = L->suff[i];
        int val = gcd(R_total_gcd, e.val);
        unsigned short mapped = map_mask(e.mask, L->right_p_len, mapLtoR);
        unsigned short mask = R_total_mask & mapped;
        append_entry(out, &len, val, e.cnt, mask);
    }
    res->suff_len = len;
}

NodeView make_view(int idx) {
    NodeView v;
    v.cnt = cnt[idx];
    v.pref_len = pref_len[idx];
    v.pref = &pref_pool[pref_off[idx]];
    v.suff_len = suff_len[idx];
    v.suff = &suff_pool[suff_off[idx]];
    v.left_p_len = left_p_len[idx];
    memcpy(v.left_primes, left_primes[idx], sizeof(int) * v.left_p_len);
    v.right_p_len = right_p_len[idx];
    memcpy(v.right_primes, right_primes[idx], sizeof(int) * v.right_p_len);
    return v;
}

void set_leaf(int idx, int val) {
    int p[10];
    int plen = factorize(val, p);

    left_p_len[idx] = plen;
    memcpy(left_primes[idx], p, sizeof(int) * plen);
    right_p_len[idx] = plen;
    memcpy(right_primes[idx], p, sizeof(int) * plen);

    unsigned short mask = (plen == 0) ? 0 : ((1 << plen) - 1);

    Entry* pref = &pref_pool[pref_off[idx]];
    pref[0].val = val;
    pref[0].cnt = 1;
    pref[0].mask = mask;
    pref_len[idx] = 1;

    Entry* suff = &suff_pool[suff_off[idx]];
    suff[0] = pref[0];
    suff_len[idx] = 1;

    cnt[idx] = (val > 1) ? 1 : 0;
}

void merge_node(int idx, int L, int R) {
    NodeView res;
    res.pref = &pref_pool[pref_off[idx]];
    res.suff = &suff_pool[suff_off[idx]];

    NodeView lv = make_view(L);
    NodeView rv = make_view(R);
    merge_views(&res, &lv, &rv);

    cnt[idx] = res.cnt;
    pref_len[idx] = res.pref_len;
    suff_len[idx] = res.suff_len;
    left_p_len[idx] = res.left_p_len;
    memcpy(left_primes[idx], res.left_primes, sizeof(int) * res.left_p_len);
    right_p_len[idx] = res.right_p_len;
    memcpy(right_primes[idx], res.right_primes, sizeof(int) * res.right_p_len);
}

void build(int idx, int l, int r) {
    pref_off[idx] = pref_top;
    int cap = (r - l + 1 < 32) ? (r - l + 1) : 32;
    pref_top += cap;

    suff_off[idx] = suff_top;
    suff_top += cap;

    if (l == r) {
        set_leaf(idx, S[l]);
    } else {
        int mid = (l + r) / 2;
        build(idx * 2, l, mid);
        build(idx * 2 + 1, mid + 1, r);
        merge_node(idx, idx * 2, idx * 2 + 1);
    }
}

void update(int idx, int l, int r, int pos, int val) {
    if (l == r) {
        set_leaf(idx, val);
        return;
    }

    int mid = (l + r) / 2;
    if (pos <= mid) update(idx * 2, l, mid, pos, val);
    else update(idx * 2 + 1, mid + 1, r, pos, val);

    merge_node(idx, idx * 2, idx * 2 + 1);
}

void collect(int idx, int l, int r, int ql, int qr, int* nodes, int* cnt_nodes) {
    if (ql <= l && r <= qr) {
        nodes[(*cnt_nodes)++] = idx;
        return;
    }

    int mid = (l + r) / 2;
    if (ql <= mid) collect(idx * 2, l, mid, ql, qr, nodes, cnt_nodes);
    if (qr > mid) collect(idx * 2 + 1, mid + 1, r, ql, qr, nodes, cnt_nodes);
}

int main(void) {
    sieve();

    int N, M;
    scanf("%d %d", &N, &M);

    for (int i = 1; i <= N; i++) scanf("%d", &S[i]);

    build(1, 1, N);

    while (M--) {
        int T, A, B;
        scanf("%d %d %d", &T, &A, &B);

        if (T == 1) {
            update(1, 1, N, A, B);
        } else {
            int nodes[64];
            int node_cnt = 0;
            collect(1, 1, N, A, B, nodes, &node_cnt);

            Entry A_pref[32], A_suff[32], B_pref[32], B_suff[32];
            NodeView accum, tempB;

            accum.pref = A_pref;
            accum.suff = A_suff;
            accum.pref_len = 0;
            accum.suff_len = 0;
            accum.cnt = 0;

            tempB.pref = B_pref;
            tempB.suff = B_suff;

            for (int i = 0; i < node_cnt; i++) {
                NodeView next = make_view(nodes[i]);
                if (accum.pref_len == 0) {
                    copy_view(&accum, &next);
                } else {
                    merge_views(&tempB, &accum, &next);
                    NodeView tmp = accum;
                    accum = tempB;
                    tempB = tmp;
                }
            }

            printf("%lld\n", accum.cnt);
        }
    }

    return 0;
}
